// Simple application for agent to work on
const express = require('express');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

/**
 * Evaluate a caller-supplied rule expression against the request.
 * The request body should contain:
 *   - rule: a JavaScript expression string, e.g., "ctx.amount > 100"
 *   - context: an object that will be available as `ctx` inside the expression
 * The function returns the result of the expression evaluation.
 */
function evalRule(req) {
  const expr = req.body.rule; // e.g., 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  // Dynamically evaluate the expression with `ctx` and `req` in scope.
  // NOTE: This uses Function constructor for flexibility as per the spec.
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// POST endpoint to evaluate a rule against request context
app.post('/check', (req, res) => {
  try {
    const result = evalRule(req);
    res.json({ result });
  } catch (err) {
    console.error('Rule evaluation error:', err);
    res.status(400).json({ error: 'Invalid rule expression' });
  }
});

// Example users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Start the server when this file is run directly
if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

